         LEFT join ${database.prefix.order}hou_order_base oob ON oge.order_id = oob.order_id
where oge.shop_id = #{shopId}
  and oge.explain_content is null

    AND oob.order_gate_shop_id = #{shopGateId}

select goods_name as goodName, sum(oog.order_goods_num) sales FROM ${database.prefix.order}hou_order_base oob, ${database.prefix.order}hou_order_goods oog where oob.order_id = oog.order_id and oob.order_status BETWEEN 3 and 6 and oob.shop_id = #{shopId} and date_format(oob.payment_time, '%Y-%m-%d') > date_format(subdate(now(), 30), '%Y-%m-%d')
AND oob.order_gate_shop_id = #{shopGateId}
group by oog.common_id order by sum(oog.order_goods_num) desc limit 30

SELECT count( * ) OrderCount, sum(if(oog.drop_shipping = 2 ,oob.order_payment_amount,(oob.order_supply_amount + order_shipping_fee)) ) OrderTotalPrice FROM ${database.prefix.order}hou_order_base oob left join ${database.prefix.order}hou_order_goods oog on oob.order_id = oog.order_id WHERE DATE_FORMAT( oob.order_create_time, '%Y-%c-%d' ) = DATE_FORMAT( now( ), '%Y-%c-%d' )
AND oob.order_type = #{shopType} AND oob.shop_id = #{shopId}
AND oog.deliver_shop_id = #{shopId}
AND oob.order_shop_hidden = 0 AND oob.order_status NOT IN ( 1, 7) group by oob.order_id

SELECT sum(if(oog.drop_shipping = 2 ,oob.order_payment_amount,(oob.order_supply_amount + order_shipping_fee)) ) salesVolumeTotalPrice FROM ${database.prefix.order}hou_order_base oob left join ${database.prefix.order}hou_order_goods oog on oob.order_id = oog.order_id WHERE DATE_FORMAT( oob.order_create_time, '%Y-%c-%d' ) = DATE_FORMAT( now( ), '%Y-%c-%d' )
AND oob.order_type = #{shopType} AND oob.shop_id = #{shopId}
AND oog.deliver_shop_id = #{shopId}
AND oob.order_shop_hidden = 0 AND oob.order_status NOT IN ( 1, 7) AND oob.order_refund_status != 2 AND oob.order_return_status != 2 group by oob.order_id

SELECT count(*) OrderCount, oob.order_id, sum(if(oog.drop_shipping = 2 ,oob.order_payment_amount,(oob.order_supply_amount + order_shipping_fee)) ) OrderTotalPrice FROM ${database.prefix.order}hou_order_base oob left join ${database.prefix.order}hou_order_goods oog on oob.order_id = oog.order_id WHERE oob.order_create_time >= subdate( curdate(), IF ( date_format( curdate(), '%w' ) = 0, 7, date_format( curdate(), '%w' ))- 1 ) AND oob.order_create_time <= subdate( curdate(), IF ( date_format( curdate(), '%w' ) = 0, 7, date_format( curdate(), '%w' ))- 7 )
AND oob.order_type = #{shopType} AND oob.shop_id = #{shopId}
AND oog.deliver_shop_id = #{shopId}
AND oob.order_shop_hidden = 0 AND oob.order_status NOT IN ( 1, 7) group by oob.order_id

SELECT sum(if(oog.drop_shipping = 2 ,oob.order_payment_amount,(oob.order_supply_amount + order_shipping_fee)) ) salesVolumeTotalPrice FROM ${database.prefix.order}hou_order_base oob left join ${database.prefix.order}hou_order_goods oog on oob.order_id = oog.order_id WHERE oob.order_create_time >= subdate( curdate(), IF ( date_format( curdate(), '%w' ) = 0, 7, date_format( curdate(), '%w' ))- 1 ) AND oob.order_create_time <= subdate( curdate(), IF ( date_format( curdate(), '%w' ) = 0, 7, date_format( curdate(), '%w' ))- 7 )
AND oob.order_type = #{shopType} AND oob.shop_id = #{shopId}
AND oog.deliver_shop_id = #{shopId}
AND oob.order_shop_hidden = 0 AND oob.order_status NOT IN (1,7) AND oob.order_refund_status != 2 AND oob.order_return_status != 2 group by oob.order_id

SELECT count(*) OrderCount, sum(if(oog.drop_shipping = 2 ,oob.order_payment_amount,(oob.order_supply_amount + order_shipping_fee)) ) OrderTotalPrice FROM ${database.prefix.order}hou_order_base oob left join ${database.prefix.order}hou_order_goods oog on oob.order_id = oog.order_id WHERE 1 = 1
AND oob.order_type = #{shopType} AND oob.shop_id = #{shopId}
