SELECT sum(if(oog.drop_shipping = 2 ,oob.order_payment_amount,(oob.order_supply_amount + order_shipping_fee)) ) salesVolumeTotalPrice FROM ${database.prefix.order}hou_order_base oob left join ${database.prefix.order}hou_order_goods oog on oob.order_id = oog.order_id WHERE 1 = 1
