SELECT oob.order_id, oob.shop_id, oob.buyer_user_id as userId, oob.shop_name, oob.order_last_return_time, oob.order_status, oob.order_buyer_evaluation_status, oob.order_shipping_code, oob.order_shipping_fee, oob.order_delay_status, oob.order_create_time, oob.order_receiver_name, oob.pay_code, oob.order_payment_amount, oob.order_goods_amount, oob.order_return_status, oob.order_refund_status, oob.order_barter_status, oor.return_cash, oob.integral_goods, oob.total_integral, oob.is_gift_order, oob.payment_code,oob.order_barter_status FROM ${database.prefix.order}hou_order_base oob LEFT join ${database.prefix.order}hou_order_return oor ON oob.order_id = oor.order_id WHERE oob.order_is_shop_take <> 1 and oob.original_order IS NULL AND ( oob.virtual_goods != 0 OR oob.virtual_goods IS NULL )
