SELECT ob.order_id, ( if(oog.drop_shipping = 1,sob.goods_payment_amount,oog.order_goods_payment_amount) - oog.shipping_fee ) AS order_payment_amount, ( if(oog.drop_shipping = 1,sob.goods_price_sum,oog.order_goods_amount)) AS order_supply_amount, oog.order_rpt_price, oog.shipping_fee, if(oog.drop_shipping = 1,sob.supper_commission,oog.order_goods_commission) AS order_commission_fee, ob.order_create_time, ob.order_finished_time, ob.buyer_user_id, ob.buyer_user_name, ob.base_member_discount , ob.distribution_discount as orderDiscountFee, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount FROM ${database.prefix.order}hou_order_base ob left join ${database.prefix.order}hou_order_goods oog on ob.order_id = oog.order_id LEFT join ${database.prefix.order}hou_order_commission oc ON ob.order_id = oc.order_id LEFT join ${database.prefix.order}hou_order_supplier_base sob on sob.order_id = ob.order_id and oog.deliver_shop_id = sob.supplier_shop_id LEFT JOIN ${database.prefix.goods}hou_goods_base gb on oog.goods_id = gb.goods_id WHERE ob.order_status IN ( '6', '9' ) and order_supply_is_settlement = 1 AND gb.supplier_goods_id = sob.goods_id
and ob.order_finished_time >= #{param.osStartDate}
and ob.order_finished_time < #{param.osEndDate}
and (ob.shop_id = #{param.shopId} or oog.deliver_shop_id = #{param.shopId})
and ob.order_supply_settlement_id = #{param.orderSettlementId}
group by ob.order_id,oog.goods_id

SELECT ob.order_id, (oog.order_goods_payment_amount - oog.shipping_fee) as order_payment_amount, sob.goods_price_sum AS order_supply_amount, oog.order_rpt_price, oog.shipping_fee, sob.supper_commission AS order_commission_fee, ob.order_create_time, ob.order_finished_time, ob.buyer_user_id, ob.buyer_user_name, ob.base_member_discount, oc.one_tg_commission + two_tg_commission as tg_commission , oc.fx_commission, sob.goods_price_sum, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount FROM ${database.prefix.order}hou_order_base ob left join ${database.prefix.order}hou_order_goods oog on ob.order_id = oog.order_id LEFT join ${database.prefix.order}hou_order_commission oc ON ob.order_id = oc.order_id LEFT join ${database.prefix.order}hou_order_supplier_base sob on sob.order_id = ob.order_id WHERE ( ob.order_status IN ('6', '9') or (ob.virtual_goods = 0 and is_cancel= 2)) and ob.order_is_settlement = 1 and oog.drop_shipping =1 and ob.payment_code != 3
and ob.order_finished_time >= #{baseMap.osStartDate}
and ob.order_finished_time <= #{baseMap.osEndDate}
and ob.shop_id = #{baseMap.shopId}
and ob.order_settlement_id = #{baseMap.orderSettlementId}
group by ob.order_id,oog.goods_id

SELECT ob.order_id, ( oog.order_goods_payment_amount - oog.shipping_fee ) order_payment_amount, ob.order_supply_amount, oog.order_rpt_price, oog.shipping_fee, oog.order_goods_commission AS order_commission_fee, ob.order_create_time, ob.order_finished_time, ob.buyer_user_id, ob.buyer_user_name, ob.base_member_discount, oc.one_tg_commission + two_tg_commission as tg_commission, oc.fx_commission, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount, oog.order_goods_amount FROM ${database.prefix.order}hou_order_base ob left join ${database.prefix.order}hou_order_goods oog on ob.order_id = oog.order_id LEFT join ${database.prefix.order}hou_order_commission oc ON ob.order_id = oc.order_id WHERE ( ob.order_status IN ( '6', '9' ) OR ( ob.virtual_goods = 0 AND is_cancel = 2 ) ) AND ob.order_is_settlement = 1 and ob.payment_code != 3
and ob.order_finished_time >= #{baseMap.osStartDate}
and ob.order_finished_time < #{baseMap.osEndDate}
and ob.shop_id = #{baseMap.shopId}
and ob.order_settlement_id = #{baseMap.orderSettlementId}
and ob.order_settlement_time like concat('%',#{baseMap.osDatetime},'%')
group by ob.order_id,oog.goods_id

