SELECT oob.order_id, oob.order_create_time, oob.buyer_user_name, oob.order_payment_amount, oob.order_status, oob.order_shipping_fee, oob.pay_code, oob.order_shipping_code, oob.order_receiver_name, oob.order_receiver_address, oob.order_receiver_contact, oob.order_refund_status, oob.order_return_status, oob.order_barter_status, oe.express_pinyin, oob.virtual_goods, oob.period_of_validity, oob.past_due, oob.redeem_code, oob.is_cancel, oob.order_goods_amount, oob.distribution_discount, oob.cancel_date, oob.payment_code, oob.giveaway_info, oog.drop_shipping, oob.order_rpt_price, oob.base_member_discount, oob.plus_discount, oob.manjian_discount, oob.manzhe_discount, oob.order_adjust_fee, oob.voucher_price, (select sum( og.order_goods_num ) FROM ${database.prefix.order}hou_order_goods og where og.order_id = oob.order_id) as orderGoodsNum, oob.plus_order FROM ${database.prefix.order}hou_order_base oob LEFT JOIN ${database.prefix.base}hou_base_express oe ON oe.express_id = oob.order_shipping_express_id left join ${database.prefix.order}hou_order_goods oog on oob.order_id = oog.order_id left join ${database.prefix.userms}hou_user_info ui on oob.buyer_user_id = ui.user_id left join ${database.prefix.userms}hou_user_business_info uuubi on uuubi.user_id = oob.buyer_user_id WHERE oob.order_shop_hidden = 0 AND oob.order_is_shop_take <> 1 and virtual_goods = 0 AND oob.shop_id = #{param.shopId}
and ui.user_mobile = #{param.userMobile}
