SELECT oob.order_id,oob.shop_id,oob.shop_name,oob.order_gate_shop_id,oob.order_last_return_time,oob.order_status,oob.order_buyer_evaluation_status, oob.order_shipping_code,oob.order_shipping_fee,oob.order_delay_status,oob.order_create_time,oob.order_receiver_name,oob.pay_code,oob.order_goods_amount, oob.order_payment_amount,oob.payment_number,oob.order_refund_amount,oob.order_refund_status,oob.order_return_status,oob.groupbuy_status,oob.order_buy_id, oob.order_promotion_id,oob.virtual_goods,oob.period_of_validity,past_due,redeem_code,redeem_code_url,payment_code,orp.return_method_type,orp.processing_results, orp.intervention_state,orp.platform_intervention_id,sb.shop_self_support,oob.is_gift_order,oob.order_source FROM ${database.prefix.order}hou_order_base oob left join ${database.prefix.order}hou_order_return_platform orp on oob.order_id = orp.order_id left join ${database.prefix.supplier}hou_shop_base sb on sb.supplier_shop_id = oob.shop_id left join ${database.prefix.order}hou_order_complaints ooc on ooc.order_id = oob.order_id and (ooc.is_platform = 0 and complaints_type != 5) where oob.order_is_shop_take <> 1 AND oob.order_del = 0 and oob.original_order is null and order_type = 1
