and ob.invoice_status = #{param.invoiceStatus}
GROUP BY ob.order_id order by ob.order_create_time desc

SELECT ob.order_id, ob.purchase_number, ob.shop_name, og.goods_id, og.goods_name, og.order_goods_num, og.goods_price, ob.order_discount_fee, ob.order_shipping_fee, ob.order_payment_amount, ob.order_status, ob.order_create_time , ob.invoice_status, sgb.goods_code, ob.buyer_user_id as userId, ob.payment_code, scb.common_state, opv.review_status as isApproval, ob.shop_id, ob.virtual_goods, ob.order_last_return_time, ob.order_refund_status, ob.order_return_status, ob.order_barter_status, ob.return_method_type, ob.buyer_user_name as orderReceiverName, ob.buyer_user_name as buyerUserName, oui.company_name as businessName, ob.order_receiver_address, ob.order_receiver_contact, sjb.bank_name as openingBank, sjb.bank_card_no as bankAccount FROM ${database.prefix.order}hou_order_base ob LEFT join ${database.prefix.order}hou_order_goods og ON ob.order_id = og.order_id LEFT JOIN ${database.prefix.supplier}hou_supplier_goods_base sgb ON og.goods_id = sgb.supplier_goods_id LEFT JOIN ${database.prefix.supplier}hou_supplier_common_base scb ON scb.supplier_goods_id = sgb.supplier_goods_id LEFT join ${database.prefix.order}hou_order_payment_vocher opv on ob.order_id = opv.order_id LEFT JOIN ${database.prefix.userms}hou_user_business_info oui on ob.buyer_user_id = oui.user_id LEFT JOIN ${database.prefix.supplier}hou_shop_base sb on sb.supplier_shop_id = ob.shop_id LEFT JOIN ${database.prefix.supplier}hou_supplier_shop_join_base sjb on sjb.user_id = sb.user_id WHERE ob.buyer_user_id = #{param.userId} AND ob.order_type =2
and ob.purchase_number = #{param.purchaseNumber}
and ob.order_create_time between #{param.startTime} and #{param.endTime}
and ob.order_id = #{param.orderId}
and ob.order_status = #{param.orderStatus}
and ob.order_status = 1 and ob.payment_code = 2 and opv.review_status = 1
and ob.order_status = 1 and ob.payment_code = 2 and opv.review_status = 3
GROUP BY ob.order_id order by ob.order_create_time desc

select cat_commission
from ${database.prefix.goods}hou_goods_cat
where cat_id = #{catId}

select dli.dealer_discount from ${database.prefix.supplier}hou_supplier_dealer_info sdi
    left join ${database.prefix.supplier}hou_supplier_dealer_level_info dli on sdi.level_id=dli.dealer_level_id
where sdi.shop_id = #{shopId} and dli.dealer_level_id is not null and sdi.supplier_shop_id = #{supplierShopId}

select IFNULL(SUM(og.order_goods_commission),0) as sellOnCommission FROM ${database.prefix.order}hou_order_base ob LEFT join ${database.prefix.order}hou_order_goods og on ob.order_id = og.order_id where ob.shop_id = #{param.shopId} and og.drop_shipping = 1 and ob.original_order is null and ob.payment_code != 3 and ob.pay_code != 13 and ob.order_is_settlement ='0' AND ((ob.order_status IN ( '5', '6', '9', '13' ) AND ob.virtual_goods = 1 ) OR (ob.order_status = '9' AND ob.virtual_goods = 1 AND ob.order_refund_status = 2 ) OR (ob.virtual_goods = 0 AND ob.is_cancel = 0 AND ob.order_status IN ( '6' ) ) OR (ob.virtual_goods = 0 AND ob.is_cancel = 2 AND ob.order_status IN ( '9','12' ) ) )
and ob.order_finished_time >= #{param.dBefore} and ob.order_finished_time <= now()
and ob.order_finished_time >= #{param.start} and ob.order_finished_time <= #{param.end}

select SUM(order_payment_amount) FROM ${database.prefix.order}hou_order_base ob where ob.shop_id = #{param.shopId} and ob.original_order is not null and ob.payment_code != 3 and ob.pay_code != 13 and ob.order_is_settlement ='0' AND ((ob.order_status IN ( '5', '6', '9' ) AND ob.virtual_goods = 1 ) OR (ob.order_status = '9' AND ob.virtual_goods = 1 AND ob.order_refund_status = 2 ) OR (ob.virtual_goods = 0 AND ob.is_cancel = 0 AND ob.order_status IN ( '6' ) ) OR (ob.virtual_goods = 0 AND ob.is_cancel = 2 AND ob.order_status IN ( '9','12' ) ) )
and ob.order_finished_time >= #{param.dBefore} and ob.order_finished_time <= now()
and ob.order_finished_time >= #{param.start} and ob.order_finished_time <= #{param.end}

select og.goods_name, og.goods_image, og.order_goods_num, og.shipment_quantity
FROM ${database.prefix.order}hou_order_goods og
where og.order_id = #{orderId}
and og.goods_id in

    #{goodsId}

select sum(oob.order_payment_amount) FROM ${database.prefix.order}hou_order_base oob
WHERE oob.payment_time between #{startTimeStr} and #{endTimeStr}
  AND oob.order_status NOT IN ( 1, 7)
  AND oob.shop_id = #{shopId}
  AND oob.order_shop_hidden = 0

select count(1) FROM ${database.prefix.order}hou_order_base oob
WHERE oob.payment_time between #{startTimeStr} and #{endTimeStr}
  AND oob.order_status NOT IN ( 1, 7)
  AND oob.shop_id = #{shopId}
  AND oob.order_shop_hidden = 0

