UPDATE ${database.prefix.order}hou_order_base
SET order_status = #{paidStatus},
    payment_number = #{cashierNo},
    payment_other_number = #{channelOrderNo},
    payment_time = #{paidTime}
WHERE order_id = #{orderId}
  AND order_status = #{expectedStatus}

UPDATE ${database.prefix.order}hou_order_base
SET payment_number = #{cashierNo}
WHERE order_id = #{orderId}
  AND order_status = #{expectedStatus}
  AND (payment_number IS NULL OR payment_number = '' OR payment_number = #{cashierNo})
